97	func (e *metricExporterImp) ConsumeMetrics(ctx context.Context, md pmetric.Metrics) error {
98		var batches map[string]pmetric.Metrics
99	
100		switch e.routingKey {
101		case svcRouting:
102			var errs []error
103			batches, errs = splitMetricsByResourceServiceName(md)
104			if len(errs) > 0 {
105				for _, ee := range errs {
106					e.logger.Error("failed to export metric", zap.Error(ee))
107				}
108				if len(batches) == 0 {
109					return consumererror.NewPermanent(errors.Join(errs...))
110				}
111			}
112		case resourceRouting:
113			batches = splitMetricsByResourceID(md)
114		case metricNameRouting:
115			batches = splitMetricsByMetricName(md)
116		case streamIDRouting:
117			batches = splitMetricsByStreamID(md)
118		}
119	
120		// Now assign each batch to an exporter, and merge as we go
121		metricsByExporter := map[*wrappedExporter]pmetric.Metrics{}
122		exporterEndpoints := map[*wrappedExporter]string{}
123	
124		for routingID, mds := range batches {
125			exp, endpoint, err := e.loadBalancer.exporterAndEndpoint([]byte(routingID))
126			if err != nil {
127				return err
128			}
129	
130			expMetrics, ok := metricsByExporter[exp]
131			if !ok {
132				exp.consumeWG.Add(1)
133				expMetrics = pmetric.NewMetrics()
134				metricsByExporter[exp] = expMetrics
135				exporterEndpoints[exp] = endpoint
136			}
137	
138			metrics.Merge(expMetrics, mds)
139		}
140	
141		var errs error
142		for exp, mds := range metricsByExporter {
143			start := time.Now()
144			err := exp.ConsumeMetrics(ctx, mds)
145			duration := time.Since(start)
146	
147			exp.consumeWG.Done()
148			errs = multierr.Append(errs, err)
149			e.telemetry.LoadbalancerBackendLatency.Record(ctx, duration.Milliseconds(), metric.WithAttributeSet(exp.endpointAttr))
150			if err == nil {
151				e.telemetry.LoadbalancerBackendOutcome.Add(ctx, 1, metric.WithAttributeSet(exp.successAttr))
152			} else {
153				e.telemetry.LoadbalancerBackendOutcome.Add(ctx, 1, metric.WithAttributeSet(exp.failureAttr))
154				e.logger.Debug("failed to export metrics", zap.Error(err))
155			}
156		}
157	
158		return errs
159	}
